<?php if(!isset($mailOwner,$message,$parts,$attachments,$account)){http_response_code(404);exit;} ?>
<article class="c-card" data-mail-message-preview><div class="mail-reader-actions"><a class="c-btn" href="compose.php?reply=<?= (int)$message['id'] ?>">Responder</a><?php if(($_GET['preview']??'')==='1'&&($_GET['source']??'')!=='unified'): ?><a class="c-btn-secondary" href="message.php?id=<?= (int)$message['id'] ?>&amp;folder=<?= (int)($readingFolder??0) ?>&amp;mark=<?= rawurlencode($readingMark??'all') ?>">Abrir mensagem completa</a><?php endif; ?></div><p class="mail-address">Conta: <?= mailCenterEscape($account['email']) ?></p><h2><?= mailCenterEscape($message['subject']?:'(sem assunto)') ?></h2><p>De: <?= mailCenterEscape($message['sender']) ?></p><?php $recipients=json_decode($message['recipients'],true)?:[]; ?><p>Para: <?= mailCenterEscape($recipients['to']??'') ?></p><p>Cc: <?= mailCenterEscape($recipients['cc']??'') ?></p>
<?php if($parts['text']!==''): ?><pre class="mail-body-text"><?= mailCenterEscape($parts['text']) ?></pre><?php endif; ?>
<?php if($parts['html']!==''): ?><details <?= $parts['text']===''?'open':'' ?>><summary>Visualização HTML protegida · imagens externas bloqueadas</summary><iframe title="Conteúdo HTML da mensagem" class="mail-body-frame" sandbox referrerpolicy="no-referrer" src="message_body.php?id=<?= (int)$message['id'] ?>"></iframe></details><?php endif; ?>
<?php if($attachments): ?><h3>Anexos</h3><?php foreach($attachments as$file): ?><p><a href="attachment.php?id=<?= (int)$file['id'] ?>"><?= mailCenterEscape($file['filename']) ?></a> · <?= number_format((int)$file['byte_size']/1024,0,',','.') ?> KB</p><?php endforeach; ?><p>Downloads limitados a 2 MB por arquivo no piloto. Para arquivos maiores, use o provedor original.</p><?php endif; ?></article>

